-- Set: Celebrations: Classic Collection (cel25c) -- 2021/10/08
insert into sets (category_slug, category_name, slug, name, is_visible)
  values ('sword-shield', 'Sword & Shield', 'celebrations-classic-collection', 'Celebrations: Classic Collection', false)
  on conflict (slug) do nothing;

with s as (select id from sets where slug = 'celebrations-classic-collection'),
inserted_cards as (
  insert into cards (set_id, number, name, rarity, image_url, pokemon_type)
  select s.id, v.number, v.name, v.rarity, v.image_url, v.pokemon_type
  from s, (values
    (2, 'Blastoise', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/2_A_hires.png', 'water'),
    (4, 'Charizard', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/4_A_hires.png', 'fire'),
    (15, 'Venusaur', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/15_A_hires.png', 'grass'),
    (16, 'Here Comes Team Rocket!', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/15_B_hires.png', NULL),
    (17, 'Rocket''s Zapdos', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/15_C_hires.png', 'lightning'),
    (18, 'Claydol', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/15_D_hires.png', 'fighting'),
    (73, 'Imposter Professor Oak', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/73_A_hires.png', NULL),
    (8, 'Dark Gyarados', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/8_A_hires.png', 'water'),
    (24, '_____''s Pikachu', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/24_A_hires.png', 'lightning'),
    (20, 'Cleffa', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/20_A_hires.png', 'colorless'),
    (66, 'Shining Magikarp', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/66_A_hires.png', 'water'),
    (9, 'Team Magma''s Groudon', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/9_A_hires.png', 'fighting'),
    (86, 'Rocket''s Admin.', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/86_A_hires.png', NULL),
    (88, 'Mew ex', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/88_A_hires.png', 'psychic'),
    (93, 'Gardevoir ex δ', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/93_A_hires.png', 'fire'),
    (19, 'Umbreon ★', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/17_A_hires.png', 'darkness'),
    (109, 'Luxray GL LV.X', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/109_A_hires.png', 'lightning'),
    (145, 'Garchomp C LV.X', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/145_A_hires.png', 'colorless'),
    (107, 'Donphan', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/107_A_hires.png', 'fighting'),
    (113, 'Reshiram', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/113_A_hires.png', 'fire'),
    (114, 'Zekrom', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/114_A_hires.png', 'lightning'),
    (54, 'Mewtwo-EX', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/54_A_hires.png', 'psychic'),
    (97, 'Xerneas-EX', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/97_A_hires.png', 'fairy'),
    (76, 'M Rayquaza-EX', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/76_A_hires.png', 'colorless'),
    (60, 'Tapu Lele-GX', 'mega_hyper_rare', 'https://images.pokemontcg.io/cel25c/60_A_hires.png', 'psychic')
  ) as v(number, name, rarity, image_url, pokemon_type)
  on conflict (set_id, number) do nothing
  returning id, rarity
)
insert into card_variants (card_id, variant, price_sek, stock)
select ic.id, x.variant, 0, 0
from inserted_cards ic
cross join lateral (
  select case when ic.rarity = 'rare' then 'holo' else 'normal' end as variant
  union all
  select 'reverse_holo' where ic.rarity in ('common','rare')
) as x(variant)
on conflict (card_id, variant) do nothing;

